kind: Deployment
metadata:
  name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}
  labels:
    {{- include "free5gc-upf.labels" $ | nindent 4 }}
    project: {{ $.Values.global.projectName }}
    nf: {{ .name }}
spec:
  {{- if not .autoscaling.enabled }}
  replicas: {{ .replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "free5gc-upf.selectorLabels" $ | nindent 6 }}
      project: {{ $.Values.global.projectName }}
      nf: {{ .name }}
  template:
    metadata:
      annotations:
        {{- include "free5gc-upf.psaupf1Annotations" $ | nindent 8 }}
        {{- if $.Values.global.upf.multus.enabled }}
        k8s.v1.cni.cncf.io/networks: '[
            { "name": "{{ $.Values.global.upf.multus.n9network.name }}-{{ include "free5gc-upf.fullname" $ }}",
              "interface": "n9",
              "ips": [ "{{ $.Values.global.upf.multus.psaupf1.n9if.ipAddress }}/{{ $.Values.global.upf.multus.n9network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.upf.multus.n9network.gatewayIP }}" ]
            },
            { "name": "{{ $.Values.global.upf.multus.n6network.name }}-{{ include "free5gc-upf.fullname" $ }}",
              "interface": "n6",
              "ips": [ "{{ $.Values.global.upf.multus.psaupf1.n6if.ipAddress }}/{{ $.Values.global.upf.multus.n6network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.upf.multus.n6network.gatewayIP }}" ]
            },
            { "name": "{{ $.Values.global.upf.multus.n4network.name }}-{{ include "free5gc-upf.fullname" $ }}",
              "interface": "n4",
              "ips": [ "{{ $.Values.global.upf.multus.psaupf1.n4if.ipAddress }}/{{ $.Values.global.upf.multus.n4network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.upf.multus.n4network.gatewayIP }}" ]
            }
            ]'
        {{- end }}
        checksum/config: {{ include (print $.Template.BasePath "/psaupf1/psaupf1-configmap.yaml") $ | sha256sum }}
      labels:
        {{- include "free5gc-upf.selectorLabels" $ | nindent 8 }}
        project: {{ $.Values.global.projectName }}
        nf: {{ .name }}
    spec:
      serviceAccountName: {{ printf "%s-%s" $.Chart.Name $.Release.Name | trunc 63 | trimSuffix "-" }}
      automountServiceAccountToken: false
      imagePullSecrets:
        {{- toYaml .imagePullSecrets | nindent 8 }}
      securityContext:
        {{- toYaml .podSecurityContext | nindent 8 }}
      containers:
      - name: {{ .name }}
        image: {{ .image.name }}:{{ .image.tag | default $.Chart.AppVersion }}
        imagePullPolicy: {{ .image.pullPolicy }}
        securityContext:
          {{- toYaml .securityContext | nindent 10 }}
        ports:
        - name: n4
          containerPort: 8805
          protocol: UDP
        command:
          - "/sbin/tini"
          - "--"
          - "{{ .volume.mount }}/wrapper.sh"
        {{- if .readinessProbe.enabled }}
        readinessProbe:
          {{- if .readinessProbe.httpGet }}
          httpGet:
            {{- toYaml .readinessProbe.httpGet | nindent 12 }}
          {{- end }}
          {{- if .readinessProbe.exec }}
          exec:
            {{- toYaml .readinessProbe.exec | nindent 12 }}
          {{- end }}
          initialDelaySeconds: {{ .readinessProbe.initialDelaySeconds }}
          periodSeconds: {{ .readinessProbe.periodSeconds }}
          timeoutSeconds: {{ .readinessProbe.timeoutSeconds | default 1 }}
          successThreshold: {{ .readinessProbe.successThreshold | default 1 }}
          failureThreshold: {{ .readinessProbe.failureThreshold | default 3 }}
        {{- end }}
        {{- if .livenessProbe.enabled }}
        livenessProbe:
          {{- if .livenessProbe.httpGet }}
          httpGet:
            {{- toYaml .livenessProbe.httpGet | nindent 12 }}
          {{- end }}
          {{- if .livenessProbe.exec }}
          exec:
            {{- toYaml .livenessProbe.exec | nindent 12 }}
          {{- end }}
          initialDelaySeconds: {{ .livenessProbe.initialDelaySeconds }}
          periodSeconds: {{ .livenessProbe.periodSeconds }}
          timeoutSeconds: {{ .livenessProbe.timeoutSeconds | default 10 }}
          successThreshold: {{ .livenessProbe.successThreshold | default 1 }}
          failureThreshold: {{ .livenessProbe.failureThreshold | default 3 }}
        {{- end }}
        volumeMounts:
        - mountPath: {{ .volume.mount }}
          name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-volume
        - mountPath: {{ .volume.tlsmount }}
          name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-empty-volume
        resources:
            {{- toYaml .resources | nindent 12 }}
      dnsPolicy: ClusterFirst
      restartPolicy: Always
      nodeSelector:
        {{- toYaml .nodeSelector | nindent 8 }}
      affinity:
        {{- toYaml .affinity | nindent 8 }}
      tolerations:
        {{- toYaml .tolerations | nindent 8 }}

      volumes:
      - name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-volume
        projected:
          sources:
          - configMap:
              name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-configmap
              items:
              - key: upfcfg.yaml
                path: upfcfg.yaml
              - key: wrapper.sh
                path: wrapper.sh
                mode: 0777
      - name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-empty-volume
        emptyDir: {}
{{- end }}
{{- end }}
